import numpy as np, itertools
from rdkit import Chem

def read_xyz(path):
    els, coords = [], []
    lines=open(path).read().splitlines()
    n=int(lines[0])
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return els,np.array(coords)

def write_xyz(path, els, coords, comment):
    with open(path,'w') as f:
        f.write(f"{len(els)}\n{comment}\n")
        for e,c in zip(els,coords):
            f.write(f"{e} {c[0]:.6f} {c[1]:.6f} {c[2]:.6f}\n")

def frame(u,w):
    u=np.array(u,float); u/=np.linalg.norm(u)
    w=np.array(w,float); w-=w.dot(u)*u; w/=np.linalg.norm(w)
    return np.stack([u,np.cross(u,w),w])

xels,X = read_xyz('xantphos.xyz')
xm = Chem.MolFromSmiles('CC1(C)c2cccc(P(c3ccccc3)c4ccccc4)c2Oc5c1cccc(P(c6ccccc6)c7ccccc7)5')
xm = Chem.AddHs(xm)
tels,T = read_xyz('tropene.xyz')
tm = Chem.MolFromSmiles('C1CC2CC=CC1([NH+]2Cc3ccccc3)')
tm = Chem.AddHs(tm)
els=['Pd']+xels+tels
NX=1+len(xels)

P1,P2 = X[8],X[29]
dPP=np.linalg.norm(P2-P1); dPdP=2.30
dx=np.sqrt(dPdP**2-(dPP/2)**2)
t1=np.array([-dx,-dPP/2,0.]); t2=np.array([-dx,dPP/2,0.])
cent=0.5*(X[22]+X[1])
Xn=((frame(t2-t1,np.array([-1.,0,0])).T @ frame(P2-P1,cent-0.5*(P1+P2))) @ (X-P1).T).T + t1

dbl=[b for b in tm.GetBonds() if b.GetBondTypeAsDouble()==2.0][0]
ca,cb=dbl.GetBeginAtomIdx(),dbl.GetEndAtomIdx()
nidx=7; ch2=8
dCC=np.linalg.norm(T[cb]-T[ca])
F1t=frame(T[cb]-T[ca], T[nidx]-0.5*(T[ca]+T[cb]))

def place_trop(phi, dm=2.05):
    u2=np.array([0.,np.cos(phi),np.sin(phi)])
    w2=np.cross(np.array([1.,0.,0.]),u2)
    mid=dm*np.array([1.,0.,0.])
    tca=mid+0.5*dCC*u2; tcb=mid-0.5*dCC*u2
    F2t=frame(tcb-tca,w2)
    return ((F2t.T@F1t) @ (T-T[ca]).T).T + tca

# rotors: (axis_i, axis_j, movable global idx list)
ri=xm.GetRingInfo()
nmem=[0]*xm.GetNumAtoms()
for r in ri.AtomRings():
    for i in r: nmem[i]+=1
rotors=[]
for ring in ri.AtomRings():
    if len(ring)!=6 or any(nmem[i]>1 for i in ring): continue
    ipso=P=None
    for i in ring:
        for nb in xm.GetAtomWithIdx(i).GetNeighbors():
            if nb.GetSymbol()=='P': ipso,P=i,nb.GetIdx()
    if ipso is None: continue
    ats=set(ring)
    for i in ring:
        for nb in xm.GetAtomWithIdx(i).GetNeighbors():
            if nb.GetSymbol()=='H': ats.add(nb.GetIdx())
    rotors.append((P+1, ipso+1, [i+1 for i in sorted(ats)]))
# tropene rotors (global = local + NX)
ph9=set(range(9,15))
for i in range(9,15):
    for nb in tm.GetAtomWithIdx(i).GetNeighbors():
        if nb.GetSymbol()=='H': ph9.add(nb.GetIdx())
rotors.append((ch2+NX, 9+NX, [i+NX for i in sorted(ph9)]))
grp8=set(range(8,15))|ph9
for i in range(8,15):
    for nb in tm.GetAtomWithIdx(i).GetNeighbors():
        if nb.GetSymbol()=='H': grp8.add(nb.GetIdx())
rotors.append((nidx+NX, ch2+NX, [i+NX for i in sorted(grp8)]))
print('n rotors', len(rotors))

def rotate(coords, ai, aj, mov, angle):
    ax=coords[aj]-coords[ai]; ax/=np.linalg.norm(ax)
    c,s=np.cos(angle),np.sin(angle)
    K=np.array([[0,-ax[2],ax[1]],[ax[2],0,-ax[0]],[-ax[1],ax[0],0]])
    Rm=np.eye(3)*c+s*K+(1-c)*np.outer(ax,ax)
    o=coords[ai]; nc=coords.copy()
    nc[mov]=((Rm@(coords[mov]-o).T).T)+o
    return nc

def minmov(coords, mov):
    mset=set(mov)
    A=coords[mov]
    Bm=[i for i in range(len(coords)) if i not in mset]
    return np.linalg.norm(A[:,None,:]-coords[Bm][None,:,:],axis=-1).min()

best=None
for phi in np.deg2rad(np.arange(0,180,15)):
    coords=np.vstack([np.array([[0.,0.,0.]]),Xn,place_trop(phi)])
    for it in range(3):
        for (ai,aj,mov) in rotors:
            ba=(-1,0.)
            for ang in np.deg2rad(np.arange(0,360,30)):
                md=minmov(rotate(coords,ai,aj,mov,ang),mov)
                if md>ba[0]: ba=(md,ang)
            coords=rotate(coords,ai,aj,mov,ba[1])
    D=np.linalg.norm(coords[:,None]-coords[None],axis=-1)
    inter=min(D[i,j] for i in range(1,NX) for j in range(NX,len(coords)))
    pdh=min(D[0,j] for j in range(NX,len(coords)) if els[j]=='H')
    sc=min(inter,pdh)
    print(f'phi {np.degrees(phi):5.0f} inter {inter:.2f} pdH {pdh:.2f}')
    if best is None or sc>best[0]: best=(sc,phi,coords.copy(),inter,pdh)

sc,phi,coords,inter,pdh=best
print('BEST phi',np.degrees(phi),'inter',round(inter,2),'pdH',round(pdh,2))
write_xyz('complex_fix5.xyz',els,coords,'Pd xantphos tropene cation preopt v5')
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'P':1.07,'Pd':1.39}
n=len(els)
bonds=set()
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(coords[i]-coords[j])
    if d<1.25*(cov[els[i]]+cov[els[j]]): bonds.add((i,j))
exp=set()
for b in xm.GetBonds():
    i,j=b.GetBeginAtomIdx()+1,b.GetEndAtomIdx()+1; exp.add((min(i,j),max(i,j)))
for b in tm.GetBonds():
    i,j=b.GetBeginAtomIdx()+NX,b.GetEndAtomIdx()+NX; exp.add((min(i,j),max(i,j)))
for k in (9,30,79,80): exp.add((0,k))
print('missing:',sorted(exp-bonds))
print('extra:',sorted(bonds-exp))
